local Q=upstream(...)
-- ArthasNav compatibility: preserve unsmoothed, flag-safe routing.
local function unsmoothed(flags)
 flags=tonumber(flags) or 0
 if flags~=flags or math.abs(flags)==math.huge or flags<0 then return 0 end
 flags=math.floor(flags);return flags-flags%8
end
Q.unsmoothed=unsmoothed
local function options(opts)
 local out={};for k,v in pairs(type(opts)=="table" and opts or {}) do out[k]=v end
 local C=require("anav/config");out.flags=unsmoothed(out.flags or C.path_flags or 0);return out
end
local find_path,find_paths=Q.find_path,Q.find_paths
function Q.find_path(from,to,opts,cb)return find_path(from,to,options(opts),cb)end
function Q.find_paths(pairs_list,opts,cb)return find_paths(pairs_list,options(opts),cb)end
return Q
